		this.itemManager = itemManager;
		this.clientThread = clientThread;
		this.mainPanel = mainPanel;
		this.config = config;
		this.client = client;
		this.eventBus = eventBus;
		this.pluginManager = pluginManager;


		setLayout(new BorderLayout());

		dataProvider.executeMany(new ItemProducedByQuery(nerItem.getInfoItem().getItemID()), recipes ->
			dataProvider.executeMany(new ItemDropSourcesQuery(nerItem.getInfoItem().getItemID()), dropSources ->
				dataProvider.executeMany(new ItemSoldAtQuery(nerItem.getInfoItem().getItemID()), shops ->
					dataProvider.executeMany(new ItemSpawnQuery(nerItem.getInfoItem().getItemID()), spawns ->
						SwingUtilities.invokeLater(() ->
							buildPanel(recipes, dropSources, shops, spawns))))));
	}

	private void buildPanel(List<NERProductionRecipe> recipes, List<NERDropSource> dropSources, List<NERShop> shops, List<NERSpawnItem> spawns)
	{
		GridBagConstraints containerGbc = new GridBagConstraints(0, 0, 1, 1, 1.0, 1.0, GridBagConstraints.LINE_START, GridBagConstraints.BOTH, new Insets(0, 0, 0, 0), 0, 0);
		JPanel recipeSection = createSection(SourceSectionType.RECIPES, recipes, dropSources, shops, spawns);
		JPanel container = new JPanel(new GridBagLayout());
		if (config.routeShopSources() || config.routeGroundSpawnSources())
		{
			container.add(createRouteButton(shops, spawns), new GridBagConstraints(0, 0, 1, 1, 1.0, 0.0, GridBagConstraints.LINE_START, GridBagConstraints.HORIZONTAL, new Insets(0, 0, 8, 0), 0, 0));
			containerGbc.gridy++;
		}

		container.add(recipeSection, containerGbc);
		containerGbc.gridy++;
		JPanel dropsSection = createSection(SourceSectionType.DROPS, recipes, dropSources, shops, spawns);
		container.add(dropsSection, containerGbc);
		containerGbc.gridy++;
		JPanel shopsSection = createSection(SourceSectionType.SHOPS, recipes, dropSources, shops, spawns);
		container.add(shopsSection, containerGbc);
		containerGbc.gridy++;
		JPanel spawnsSection = createSection(SourceSectionType.SPAWNS, recipes, dropSources, shops, spawns);
		container.add(spawnsSection, containerGbc);
		containerGbc.gridy++;


		JPanel wrapper = new JPanel(new BorderLayout());

		wrapper.setMaximumSize(new Dimension(220, Integer.MAX_VALUE));
		wrapper.add(container, BorderLayout.NORTH);

		JScrollPane scrollWrapper = new JScrollPane(wrapper);
		scrollWrapper.getVerticalScrollBar().setPreferredSize(new Dimension(12, 0));
		scrollWrapper.getVerticalScrollBar().setBorder(new EmptyBorder(0, 5, 0, 0));
		scrollWrapper.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, 1000));
		scrollWrapper.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);

		add(scrollWrapper, BorderLayout.CENTER);
		revalidate();
	}

	private JPanel createSection(SourceSectionType sectionType, List<NERProductionRecipe> recipes, List<NERDropSource> dropSources, List<NERShop> shops, List<NERSpawnItem> spawns)
	{
		ArrayList<JPanel> sectionItems = new ArrayList<>();
		switch (sectionType)
		{
			case RECIPES:
				recipes.forEach((recipe) ->
						sectionItems.add(new NERRecipePanel(recipe, itemManager, clientThread, mainPanel, nerItem.getInfoItem(), dataProvider)));
				break;

			case DROPS:
				if (!dropSources.isEmpty()) {
					sectionItems.add(new NERDropsPanel(new NERDropItem(nerItem.getInfoItem().getName(), nerItem.getInfoItem().getVersion(), dropSources), eventBus, pluginManager, config));
				}
				break;

			case SHOPS:
				if (!shops.isEmpty()) {
					sectionItems.add(new NERShopsPanel(shops, nerItem, itemManager, clientThread, false, mainPanel, client, eventBus, pluginManager));
				}
				break;

			case SPAWNS:
				spawns.forEach((spawnItem) ->
						sectionItems.add(new NERSpawnPanel(spawnItem, clientThread, client, eventBus, pluginManager)));
//					.limit(MAX_ENTRIES)

				break;
		}

		if (sectionItems.isEmpty())
		{
			JPanel emptyPanel = new JPanel();
			emptyPanel.setMinimumSize(new Dimension(0, 0));
			emptyPanel.setMaximumSize(new Dimension(0, 0));
			emptyPanel.setPreferredSize(new Dimension(0, 0));
			return emptyPanel;
		}

		final JPanel section = new JPanel();
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		section.setMinimumSize(new Dimension(210, 0));
		section.setMaximumSize(new Dimension(220, 0));


		final JPanel sectionHeader = new JPanel();
		sectionHeader.setLayout(new BorderLayout());
		sectionHeader.setMinimumSize(new Dimension(220, 0));
		// For whatever reason, the header extends out by a single pixel when closed. Adding a single pixel of
		// border on the right only affects the width when closed, fixing the issue.
		sectionHeader.setBorder(new CompoundBorder(
			new MatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(0, 0, 3, 1)));
		section.add(sectionHeader, BorderLayout.NORTH);

		final JButton sectionToggle = new JButton(SECTION_EXPAND_ICON);
		sectionToggle.setRolloverIcon(SECTION_EXPAND_ICON_HOVER);
		sectionToggle.setPreferredSize(new Dimension(18, 0));
		sectionToggle.setBorder(new EmptyBorder(0, 0, 0, 5));
		sectionToggle.setToolTipText("Expand");
		SwingUtil.removeButtonDecorations(sectionToggle);
		sectionHeader.add(sectionToggle, BorderLayout.WEST);

		final JLabel sectionName = new JLabel(sectionType.sectionName);
		sectionName.setForeground(ColorScheme.BRAND_ORANGE);
		sectionName.setFont(FontManager.getRunescapeBoldFont());
		sectionName.setToolTipText(sectionType.sectionDesc);
		sectionHeader.add(sectionName, BorderLayout.CENTER);

		final JPanel sectionContents = new JPanel();
		sectionContents.setLayout(new DynamicGridLayout(0, 1, 0, 10));
		sectionContents.setMinimumSize(new Dimension(220, 0));
		sectionContents.setBorder(new CompoundBorder(
			new MatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(PluginPanel.BORDER_OFFSET, 0, PluginPanel.BORDER_OFFSET, 0)));
		sectionContents.setVisible(false);
		section.add(sectionContents, BorderLayout.SOUTH);

		final MouseAdapter sectionAdapter = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				toggleSection(sectionToggle, sectionContents);
			}
		};
		sectionToggle.addActionListener(actionEvent -> toggleSection(sectionToggle, sectionContents));
		sectionName.addMouseListener(sectionAdapter);
		sectionHeader.addMouseListener(sectionAdapter);

		sectionItems.forEach(sectionContents::add);

		if (config.defaultOpenSources().contains(DefaultOpenSources.of(sectionType))) {
			toggleSection(sectionToggle, sectionContents);
		}

		return section;
	}

	private JButton createRouteButton(List<NERShop> shops, List<NERSpawnItem> spawns)
	{
		JButton routeButton = new JButton("Shortest Path to shop/spawn");
		routeButton.setPreferredSize(new Dimension(220, 30));
		routeButton.setEnabled(false);
		routeButton.setToolTipText("Checking route availability...");
		routeButton.addActionListener(event -> updateRouteButton(routeButton, shops, spawns, true));
		updateRouteButton(routeButton, shops, spawns, false);
		return routeButton;
	}

	private void updateRouteButton(JButton routeButton, List<NERShop> shops, List<NERSpawnItem> spawns, boolean requestRoute)
	{
		if (requestRoute)
		{
			routeButton.setEnabled(false);
		}

		clientThread.invokeLater(() ->
		{
			String tooltip;
			if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
			{
				tooltip = "Log in to route to an item source.";
			}
			else if (findShortestPathPlugin() == null)
			{
				tooltip = "Enable the Shortest Path plugin to use this action.";
			}
			else
			{
				Set<WorldPoint> targets = buildRouteTargets(shops, spawns);
				if (targets.isEmpty())
				{
					tooltip = "No valid enabled shop or ground-spawn locations are available.";
				}
				else
				{
					if (requestRoute)
					{
						eventBus.post(new PluginMessage("shortestpath", "path", Map.of("target", targets)));
					}
					tooltip = requestRoute
						? "Route request sent to Shortest Path. Stock and access are not guaranteed."
						: "Ask Shortest Path to route to an enabled listed shop or ground spawn. Stock and access are not guaranteed.";
				}
			}

			setRouteButtonState(routeButton, tooltip);
		});
	}

	private Set<WorldPoint> buildRouteTargets(List<NERShop> shops, List<NERSpawnItem> spawns)
	{
		Set<WorldPoint> targets = new HashSet<>();
		boolean membersWorld = client.getWorldType().contains(WorldType.MEMBERS);

		if (config.routeShopSources())
		{
			for (NERShop shop : shops)
			{
				if ((!membersWorld && shop.isMembers()) || hasKnownZeroStock(shop))
				{
					continue;
				}

				WorldPoint target = NERSourceRouteUtil.parseWorldPoint(shop.getCoords(), shop.getPlane());
				if (target != null)
				{
					targets.add(target);
				}
			}
		}

		if (config.routeGroundSpawnSources())
		{
			for (NERSpawnItem spawn : spawns)
			{
				if (!membersWorld && spawn.isMembers())
				{
					continue;
				}

				WorldPoint target = NERSourceRouteUtil.parseWorldPoint(spawn.getCoords(), spawn.getPlane());
				if (target != null)
				{
					targets.add(target);
				}
			}
		}

		return targets;
	}

	private static boolean hasKnownZeroStock(NERShop shop)
	{
		return !shop.getItems().isEmpty() && shop.getItems().stream()
			.allMatch(item -> item.getStock() != null && "0".equals(item.getStock().trim()));
	}

	private Plugin findShortestPathPlugin()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if ("Shortest Path".equals(plugin.getName()) && pluginManager.isPluginActive(plugin))
			{
				return plugin;
			}
		}
		return null;
	}

	private static void setRouteButtonState(JButton routeButton, String tooltip)
	{
		SwingUtilities.invokeLater(() ->
		{
			routeButton.setEnabled(true);
			routeButton.setToolTipText(tooltip);
		});
	}

	private void toggleSection(JButton button, JPanel contents)
	{
		boolean newState = !contents.isVisible();
		contents.setVisible(newState);
		button.setIcon(newState ? SECTION_RETRACT_ICON : SECTION_EXPAND_ICON);
		button.setRolloverIcon(newState ? SECTION_RETRACT_ICON_HOVER : SECTION_EXPAND_ICON_HOVER);
		button.setToolTipText(newState ? "Retract" : "Expand");
		SwingUtilities.invokeLater(contents::revalidate);
	}
}

